#include <stdlib.h>
#include <string.h>
#include <float.h>
/* Dense LAPJV. cost n x n row-major. x[i]=col of row i. */
int lapjv(int n, const double *c, int *x) {
    int *y = malloc(n*sizeof(int)), *free_r = malloc(n*sizeof(int)), *matches = calloc(n,sizeof(int));
    int *col = malloc(n*sizeof(int)), *pred = malloc(n*sizeof(int));
    double *v = malloc(n*sizeof(double)), *d = malloc(n*sizeof(double));
    int i,j,k,numfree=0;
    /* column reduction */
    for (j=0;j<n;j++){ y[j]=-1; }
    for (i=0;i<n;i++) x[i]=-1;
    for (j=n-1;j>=0;j--){
        double m=c[j]; int imin=0;
        for(i=1;i<n;i++){ double h=c[(size_t)i*n+j]; if(h<m){m=h;imin=i;} }
        v[j]=m;
        if(++matches[imin]==1){ x[imin]=j; y[j]=imin; }
        else if (v[j] < v[x[imin]]) { int j1=x[imin]; x[imin]=j; y[j]=imin; y[j1]=-1; }
    }
    /* reduction transfer */
    for(i=n-1;i>=0;i--){
        if(matches[i]==0) free_r[numfree++]=i;
        else if(matches[i]==1){
            int j1=x[i]; const double *ci=c+(size_t)i*n; double m=DBL_MAX;
            for(j=0;j<n;j++) if(j!=j1){ double h=ci[j]-v[j]; if(h<m) m=h; }
            v[j1]-=m;
        }
    }
    /* augmenting row reduction */
    for(int loop=0;loop<2;loop++){
        int kk=0, prvnumfree=numfree; numfree=0;
        while(kk<prvnumfree){
            i=free_r[kk++];
            const double *ci=c+(size_t)i*n;
            double umin=ci[0]-v[0], usubmin=DBL_MAX; int j1=0,j2=-1;
            for(j=1;j<n;j++){ double h=ci[j]-v[j];
                if(h<usubmin){ if(h>=umin){usubmin=h;j2=j;} else {usubmin=umin;umin=h;j2=j1;j1=j;} } }
            int i0=y[j1];
            if(umin<usubmin) v[j1]-= (usubmin-umin);
            else if(i0>=0){ j1=j2; i0=y[j2]; }
            x[i]=j1; y[j1]=i;
            if(i0>=0){
                if(umin<usubmin) free_r[--kk]=i0;
                else free_r[numfree++]=i0;
            }
        }
    }
    /* augmentation */
    for(int f=0;f<numfree;f++){
        int freerow=free_r[f], endofpath=-1, low=0, up=0, last=0;
        const double *cf=c+(size_t)freerow*n;
        for(j=0;j<n;j++){ d[j]=cf[j]-v[j]; pred[j]=freerow; col[j]=j; }
        double mn=0;
        int done=0;
        while(!done){
            if(up==low){
                last=low-1;
                mn=d[col[up++]];
                for(k=up;k<n;k++){ j=col[k]; double h=d[j];
                    if(h<=mn){ if(h<mn){ up=low; mn=h; } col[k]=col[up]; col[up++]=j; } }
                for(k=low;k<up;k++) if(y[col[k]]<0){ endofpath=col[k]; done=1; break; }
            }
            if(!done){
                int j1=col[low++]; i=y[j1];
                const double *ci=c+(size_t)i*n;
                double u1=ci[j1]-v[j1]-mn;
                for(k=up;k<n;k++){ j=col[k]; double h=ci[j]-v[j]-u1;
                    if(h<d[j]){ d[j]=h; pred[j]=i;
                        if(h==mn){ if(y[j]<0){ endofpath=j; done=1; break; } else { col[k]=col[up]; col[up++]=j; } } } }
            }
        }
        for(k=0;k<=last;k++){ int j1=col[k]; v[j1]+=d[j1]-mn; }
        do { i=pred[endofpath]; y[endofpath]=i; int j1=endofpath; endofpath=x[i]; x[i]=j1; } while(i!=freerow);
    }
    free(y);free(free_r);free(matches);free(col);free(pred);free(v);free(d);
    return 0;
}
