#include <stdlib.h>
#include <string.h>
#include <float.h>
/* sparse shortest augmenting path LAP with dense verification */
static void qsel(double *key, int *idx, int lo, int hi, int k){
    /* partially order so that first k (indices lo..lo+k-1) are smallest */
    while(hi>lo){
        double p=key[(lo+hi)/2]; int i=lo,j=hi;
        while(i<=j){ while(key[i]<p)i++; while(key[j]>p)j--;
            if(i<=j){ double t=key[i];key[i]=key[j];key[j]=t; int s=idx[i];idx[i]=idx[j];idx[j]=s; i++;j--; } }
        if(k-1<=j) hi=j; else if(k-1>=i) lo=i; else return;
    }
}
typedef struct { int *col; int len, cap; } Row;
static void addedge(Row *r, int j){ if(r->len==r->cap){ r->cap=r->cap*2+4; r->col=realloc(r->col,r->cap*sizeof(int)); } r->col[r->len++]=j; }

int lap(int n, const double *c, int *x, int K){
    int *y=malloc(n*sizeof(int)); double *v=malloc(n*sizeof(double));
    double *d=malloc(n*sizeof(double)); int *pred=malloc(n*sizeof(int));
    int *state=calloc(n,sizeof(int)); /* 0 unseen, stamp */
    int *scanned=malloc(n*sizeof(int)); int *touched=malloc(n*sizeof(int));
    int *heap=malloc((size_t)n*n*sizeof(int)>0? (size_t)(n*K*4+n)*sizeof(int):4); double *hk=malloc((size_t)(n*K*4+n)*sizeof(double));
    size_t hcap=(size_t)n*K*4+n;
    int *freer=malloc(n*sizeof(int)); int nfree=0;
    double *key=malloc(n*sizeof(double)); int *idx=malloc(n*sizeof(int));
    Row *rows=calloc(n,sizeof(Row));
    int i,j;
    if(K>n)K=n;
    for(i=0;i<n;i++)x[i]=-1;
    for(j=0;j<n;j++){y[j]=-1;v[j]=DBL_MAX;}
    int *amin=malloc(n*sizeof(int));
    for(i=0;i<n;i++){const double*ci=c+(size_t)i*n; for(j=0;j<n;j++) if(ci[j]<v[j]){v[j]=ci[j];amin[j]=i;}}
    for(j=0;j<n;j++){ i=amin[j]; if(x[i]<0){x[i]=j;y[j]=i;} else if(v[j]<v[x[i]]){ y[x[i]]=-1; x[i]=j; y[j]=i; } }
    /* build candidate edges: K smallest reduced costs per row */
    for(i=0;i<n;i++){
        const double*ci=c+(size_t)i*n;
        for(j=0;j<n;j++){key[j]=ci[j]-v[j];idx[j]=j;}
        qsel(key,idx,0,n-1,K);
        rows[i].cap=K+4; rows[i].col=malloc(rows[i].cap*sizeof(int)); rows[i].len=0;
        int hasx=0;
        for(int k=0;k<K;k++){ addedge(&rows[i],idx[k]); if(idx[k]==x[i])hasx=1; }
        if(x[i]>=0 && !hasx) addedge(&rows[i],x[i]);
    }
    /* ensure invariant: matched row's x[i] is min over its edges (reduced) - reassign else */
    for(i=0;i<n;i++) if(x[i]<0) freer[nfree++]=i;
        else { const double*ci=c+(size_t)i*n; double ux=ci[x[i]]-v[x[i]];
            for(int k=0;k<rows[i].len;k++){ j=rows[i].col[k]; if(ci[j]-v[j]<ux-1e-15){ y[x[i]]=-1; x[i]=-1; freer[nfree++]=i; break; } } }
    int stamp=0;
    for(int iter=0;;iter++){
        for(int f=0;f<nfree;f++){
            int fr=freer[f]; stamp++;
            int hs=0, ns=0, nt=0, end=-1; double mn=0;
            const double*cf=c+(size_t)fr*n;
            #define PUSH(J,K2) do{ if((size_t)hs>=hcap){hcap*=2;heap=realloc(heap,hcap*sizeof(int));hk=realloc(hk,hcap*sizeof(double));} int p=hs++; while(p>0){int q=(p-1)/2; if(hk[q]<=K2)break; heap[p]=heap[q];hk[p]=hk[q];p=q;} heap[p]=J;hk[p]=K2; }while(0)
            for(int k=0;k<rows[fr].len;k++){ j=rows[fr].col[k]; double h=cf[j]-v[j];
                if(state[j]!=stamp){state[j]=stamp; touched[nt++]=j; d[j]=h; pred[j]=fr; PUSH(j,h);}
                else if(h<d[j]){d[j]=h;pred[j]=fr;PUSH(j,h);} }
            /* scanned marker: use negative stamp */
            while(1){
                /* pop */
                int j1; double dk;
                if(hs==0){ end=-1; break; }
                j1=heap[0]; dk=hk[0]; hs--;
                if(hs>0){ int lj=heap[hs]; double lk=hk[hs]; int p=0; while(1){int q=2*p+1; if(q>=hs)break; if(q+1<hs&&hk[q+1]<hk[q])q++; if(hk[q]>=lk)break; heap[p]=heap[q];hk[p]=hk[q];p=q;} heap[p]=lj;hk[p]=lk; }
                if(state[j1]==-stamp || dk>d[j1]) continue;
                state[j1]=-stamp; mn=dk;
                if(y[j1]<0){ end=j1; break; }
                scanned[ns++]=j1;
                int r=y[j1]; const double*cr=c+(size_t)r*n;
                double base=dk-(cr[j1]-v[j1]);
                for(int k=0;k<rows[r].len;k++){ j=rows[r].col[k]; if(state[j]==-stamp)continue;
                    double h=base+cr[j]-v[j];
                    if(state[j]!=stamp){state[j]=stamp; touched[nt++]=j; d[j]=h; pred[j]=r; PUSH(j,h);}
                    else if(h<d[j]){d[j]=h;pred[j]=r;PUSH(j,h);} }
            }
            if(end<0){ /* no path in sparse graph: add all edges to this row set? add full row for fr */
                /* fallback: give fr all columns, retry */
                rows[fr].len=0; for(j=0;j<n;j++) addedge(&rows[fr],j);
                for(int k=0;k<ns;k++){ int r=y[scanned[k]]; rows[r].len=0; for(j=0;j<n;j++) addedge(&rows[r],j);} 
                /* revert nothing (v not updated yet), retry */
                f--; continue;
            }
            for(int k=0;k<ns;k++){ j=scanned[k]; v[j]+=d[j]-mn; }
            int ii; j=end;
            do{ ii=pred[j]; y[j]=ii; int t=x[ii]; x[ii]=j; j=t; }while(ii!=fr);
        }
        /* dense verification */
        nfree=0;
        for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; double ux=ci[x[i]]-v[x[i]]-1e-13; int bad=0;
            for(j=0;j<n;j++){ if(ci[j]-v[j]<ux){ addedge(&rows[i],j); bad=1; } }
            if(bad){ y[x[i]]=-1; x[i]=-1; freer[nfree++]=i; } }
        if(nfree==0)break;
    }
    for(i=0;i<n;i++)free(rows[i].col);
    free(rows);free(y);free(v);free(d);free(pred);free(state);free(scanned);free(touched);free(heap);free(hk);free(freer);free(key);free(idx);free(amin);
    return 0;
}
