import ctypes, os
import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "liblap2.so"))
_lib.lap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int]
K = int(os.environ.get("LAPK", "12"))


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if (M.shape == (n, n) and b.shape[0] == n and n > 1
                and np.all(a == a[0]) and np.all(b == a[0])):
            x = np.empty(n, dtype=np.int32)
            _lib.lap(n, M.ctypes.data, x.ctypes.data, K)
            G = np.zeros((n, n))
            G[np.arange(n), x] = a[0]
            return {"transport_plan": G}
        import ot
        return {"transport_plan": ot.lp.emd(a, b, M, check_marginals=False)}
