#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <stdio.h>
#include <time.h>
static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec*1e3+t.tv_nsec*1e-6;}
#ifndef DBG
#define DBG 0
#endif
typedef struct { int *col; double *w; int len, cap; } Row;
static inline void addedge(Row *r, int j, double w){
    if(r->len==r->cap){ r->cap=r->cap*2+8; r->col=realloc(r->col,r->cap*sizeof(int)); r->w=realloc(r->w,r->cap*sizeof(double)); }
    r->col[r->len]=j; r->w[r->len]=w; r->len++; }
static int cmpd(const void*a,const void*b){double x=*(double*)a,y=*(double*)b;return x<y?-1:x>y;}

int lap(int n, const double *c, int *x, int K, int narr){
    double T0=now();
    int i,j,k;
    int *y=malloc(n*sizeof(int)); double *v=malloc(n*sizeof(double));
    double *u=malloc(n*sizeof(double));
    double *d=malloc(n*sizeof(double)); int *pred=malloc(n*sizeof(int));
    int *state=calloc(n,sizeof(int));
    int *scanned=malloc(n*sizeof(int));
    size_t hcap=16*n; int *heap=malloc(hcap*sizeof(int)); double *hk=malloc(hcap*sizeof(double));
    int *freer=malloc(n*sizeof(int)); int nfree=0;
    Row *rows=calloc(n,sizeof(Row));
    for(j=0;j<n;j++) v[j]=c[j];
    for(i=1;i<n;i++){const double*ci=c+(size_t)i*n; for(j=0;j<n;j++){ double h=ci[j]; v[j]=h<v[j]?h:v[j]; }}
    /* threshold from sample rows */
    double *tmp=malloc(n*sizeof(double)); int ns_=8; double ts[8];
    for(int s=0;s<ns_;s++){ i=(int)((long)s*n/ns_); const double*ci=c+(size_t)i*n; double m=DBL_MAX;
        for(j=0;j<n;j++){tmp[j]=ci[j]-v[j]; if(tmp[j]<m)m=tmp[j];}
        for(j=0;j<n;j++)tmp[j]-=m;
        qsort(tmp,n,sizeof(double),cmpd); ts[s]=tmp[K<n?K-1:n-1]; }
    qsort(ts,ns_,sizeof(double),cmpd); double t=ts[ns_/2];
    free(tmp);
    double T1=now();
    for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; double m=DBL_MAX;
        for(j=0;j<n;j++){ double h=ci[j]-v[j]; m=h<m?h:m; }
        u[i]=m; double th=m+t; Row*R=&rows[i]; R->cap=2*K+8; R->col=malloc(R->cap*sizeof(int)); R->w=malloc(R->cap*sizeof(double));
        for(j=0;j<n;j++){ if(ci[j]-v[j]<=th) addedge(R,j,ci[j]); } }
    double T2=now();
    for(i=0;i<n;i++){x[i]=-1;} for(j=0;j<n;j++)y[j]=-1;
    for(i=n-1;i>=0;i--) freer[nfree++]=i;
    long totscan=0;
    int stamp=0;
    for(int iter=0;;iter++){
      /* ARR */
      for(int loop=0;loop<narr;loop++){
        int kk=0, prv=nfree; nfree=0; long ops=0, cap=4L*n;
        while(kk<prv){
            i=freer[kk++];
            Row*R=&rows[i];
            double umin=DBL_MAX, usub=DBL_MAX; int j1=-1,j2=-1;
            for(k=0;k<R->len;k++){ j=R->col[k]; double h=R->w[k]-v[j];
                if(h<usub){ if(h>=umin){usub=h;j2=j;} else {usub=umin;j2=j1;umin=h;j1=j;} } }
            if(j2<0){ freer[nfree++]=i; continue; }
            int i0=y[j1];
            if(umin<usub) v[j1]-=(usub-umin);
            else if(i0>=0){ j1=j2; i0=y[j2]; }
            x[i]=j1; y[j1]=i;
            if(i0>=0){ x[i0]=-1; if(umin<usub && ++ops<cap) freer[--kk]=i0; else freer[nfree++]=i0; }
        }
      }
      for(int f=0;f<nfree;f++){
        int fr=freer[f]; stamp++;
        int hs=0, ns=0, end=-1; double mn=0;
        #define PUSH(J,K2) do{ if((size_t)hs>=hcap){hcap*=2;heap=realloc(heap,hcap*sizeof(int));hk=realloc(hk,hcap*sizeof(double));} int p=hs++; while(p>0){int q=(p-1)>>1; if(hk[q]<=K2)break; heap[p]=heap[q];hk[p]=hk[q];p=q;} heap[p]=J;hk[p]=K2; }while(0)
        { Row*R=&rows[fr];
          for(k=0;k<R->len;k++){ j=R->col[k]; double h=R->w[k]-v[j];
            if(state[j]!=stamp){state[j]=stamp; d[j]=h; pred[j]=fr; PUSH(j,h);}
