                if(st!=stamp){state[j]=stamp; d[j]=h; pred[j]=r; PUSH(j,h);}
                else if(h<d[j]){d[j]=h;pred[j]=r;PUSH(j,h);} }
        }
        totscan+=ns;
        if(end<0){
            /* infeasible in sparse graph: densify rows involved and retry */
            Row*R=&rows[fr]; R->len=0; for(j=0;j<n;j++) addedge(R,j,c[(size_t)fr*n+j]);
            for(k=0;k<ns;k++){ int r=y[scanned[k]]; R=&rows[r]; R->len=0; for(j=0;j<n;j++) addedge(R,j,c[(size_t)r*n+j]); }
            f--; continue;
        }
        for(k=0;k<ns;k++){ j=scanned[k]; v[j]+=d[j]-mn; }
        int ii; j=end;
        do{ ii=pred[j]; y[j]=ii; int tt=x[ii]; x[ii]=j; j=tt; }while(ii!=fr);
      }
