      nfree=0;
      for(i=0;i<n;i++){ const double*ci=c+(size_t)i*n; double ux=ci[x[i]]-v[x[i]]-1e-12; int bad=0;
          double m=DBL_MAX; for(j=0;j<n;j++){ double h=ci[j]-v[j]; m=h<m?h:m; }
          if(m<ux){ for(j=0;j<n;j++){ if(ci[j]-v[j]<ux){ int dup=0; Row*R=&rows[i]; for(k=0;k<R->len;k++) if(R->col[k]==j){dup=1;break;} if(!dup) addedge(R,j,ci[j]); } }
            bad=1; }
          if(bad){ y[x[i]]=-1; x[i]=-1; freer[nfree++]=i; } }
      if(DBG) fprintf(stderr,"iter %d nfree %d\n",iter,nfree);
      if(nfree==0)break;
    }
    if(DBG) fprintf(stderr,"colmin %.3f build %.3f total %.3f scans %ld\n",T1-T0,T2-T1,now()-T0,totscan);
    for(i=0;i<n;i++){free(rows[i].col);free(rows[i].w);}
    free(rows);free(y);free(v);free(u);free(d);free(pred);free(state);free(scanned);free(heap);free(hk);free(freer);
    return 0;
}
